// At most 100 ms in a submission, in addition to the absolute frame limit.
#define MAX_SUBMIT_MS 100

// The C ABI version. A game compares `arcade_abi_version()` against the
// value it was compiled with; a mismatch means a different header.
#define ARCADE_SDK_ABI_VERSION 2

// The largest `RpcRequest` `arcade_poll_request` will ever hand out; a
// buffer this big never sees `ARCADE_STATUS_BUFFER_TOO_SMALL`.
#define ARCADE_MAX_REQUEST_BYTES 1048576

// The largest `Input` `arcade_poll_input` will ever hand out; a buffer this
// big never sees `ARCADE_STATUS_BUFFER_TOO_SMALL`.
#define ARCADE_MAX_INPUT_BYTES 65536

// Absolute sample-frame limit. Also limit each submission to
// `sample_rate * ARCADE_MAX_AUDIO_MS / 1000` frames; split longer buffers.
#define ARCADE_MAX_AUDIO_FRAMES 16384

// Maximum duration per audio submission, including the timed variant.
#define ARCADE_MAX_AUDIO_MS 100

// `ArcadeAudio.flags`: the source restarted,
// jumped or lost samples. The first buffer after it starts a new run.
#define ARCADE_AUDIO_DISCONTINUITY 1

// `arcade_report`'s instance for a `LogLine` about the whole process.
#define ARCADE_NO_INSTANCE 4294967295

// `ArcadeFrame.flags`: the rows are bottom-up (`glReadPixels`, a GL render
// texture read back in Unity).
#define ARCADE_FRAME_FLIP_Y 1

// Result of every SDK call. `arcade_last_error()` has the details of any
// non-OK status, on the calling thread.
typedef enum {
    ARCADE_STATUS_OK = 0,
    // `arcade_init` has not succeeded (or `arcade_shutdown` ran).
    ARCADE_STATUS_NOT_INITIALIZED = 1,
    // `arcade_init` called twice without a shutdown in between.
    ARCADE_STATUS_ALREADY_INITIALIZED = 2,
    // A null pointer, a zero length where data is required, or bad UTF-8.
    ARCADE_STATUS_INVALID_ARGUMENT = 3,
    // The bytes are not the protobuf message the function expects.
    ARCADE_STATUS_DECODE_ERROR = 4,
    // The message decoded but is not acceptable (unknown challenge, value
    // out of range, response of the wrong type, ...).
    ARCADE_STATUS_VALIDATION_ERROR = 5,
    // `arcade_poll_request`: the buffer is smaller than the next request,
    // whose size was written to `out_len`. The request stays queued.
    ARCADE_STATUS_BUFFER_TOO_SMALL = 6,
    // `arcade_respond`/`arcade_fail`: no such pending request (answered
    // already, timed out, or never issued).
    ARCADE_STATUS_UNKNOWN_REQUEST = 7,
    // A caller asked for a service or method the game does not serve.
    ARCADE_STATUS_UNKNOWN_METHOD = 8,
    // Too many requests, or audio ingress is full/busy. Audio is rejected
    // as a whole; keep the source timeline advancing and mark any lost time.
    ARCADE_STATUS_QUEUE_FULL = 9,
    // `arcade_shutdown` could not join every SDK thread in time. Do NOT
    // unload the DLL; call `arcade_shutdown` again later or let the process
    // exit.
    ARCADE_STATUS_SHUTDOWN_INCOMPLETE = 10,
    // The SDK panicked internally. Report it to us with the log file.
    ARCADE_STATUS_PANIC = 11,
    // Anything else (a socket that could not be bound, ...).
    ARCADE_STATUS_INTERNAL = 12,
    // No such instance: it is not below `arcade_instance_count()`.
    ARCADE_STATUS_UNKNOWN_INSTANCE = 13,
} ArcadeStatus;

// How a frame's pixels are laid out, byte by byte.
typedef enum {
    // R, G, B, A (A ignored). `GL_RGBA` / `DXGI_FORMAT_R8G8B8A8_UNORM`.
    ARCADE_PIXEL_FORMAT_RGBA8 = 1,
    // B, G, R, A (A ignored). `DXGI_FORMAT_B8G8R8A8_UNORM`, Unreal's `FColor`.
    ARCADE_PIXEL_FORMAT_BGRA8 = 2,
    // R, G, B.
    ARCADE_PIXEL_FORMAT_RGB8 = 3,
} ArcadePixelFormat;

// How a run of sound's samples are stored. Either way they are interleaved
// (left, right, left, ... in stereo), `InitRequest.audio.channels` per
// sample frame.
typedef enum {
    // 32-bit float, -1.0..1.0 (louder is clipped). Unity's
    // `OnAudioFilterRead`, Unreal's submix buffers, FMOD and Wwise mixes.
    ARCADE_SAMPLE_FORMAT_F32 = 1,
    // Signed 16-bit integer.
    ARCADE_SAMPLE_FORMAT_S16 = 2,
} ArcadeSampleFormat;

// One rendered frame of one instance, for `arcade_submit_frame`. The DLL
// copies the pixels before returning.
typedef struct {
    // Increasing, per instance: the game's own frame counter will do.
    uint64_t frame_index;
    // The game's clock, seconds.
    double game_time_s;
    // `height` rows of `stride` bytes (the last one may stop at the image's
    // width).
    const uint8_t *pixels;
    // Must equal `InitRequest.video`.
    uint32_t width;
    uint32_t height;
    // Bytes from one row to the next; 0 = `width` times the pixel size.
    uint32_t stride;
    // An `ArcadePixelFormat` value.
    uint32_t format;
    // `ARCADE_FRAME_FLIP_Y`, or 0.
    uint32_t flags;
    // Must be 0.
    uint32_t reserved;
} ArcadeFrame;

// One run of sound one instance just mixed, for `arcade_submit_audio`. The
// DLL copies the samples before returning.
typedef struct {
    // `frame_count` sample frames of `InitRequest.audio.channels` samples
    // each, interleaved, in `format`: `float*` for F32, `int16_t*` for S16.
    const void *samples;
    // Sample frames (per channel), 1..`ARCADE_MAX_AUDIO_FRAMES`.
    uint32_t frame_count;
    // An `ArcadeSampleFormat` value.
    uint32_t format;
    // 0, or `ARCADE_AUDIO_DISCONTINUITY` after a source reset or loss.
    uint32_t flags;
    // Must be 0.
    uint32_t reserved;
} ArcadeAudio;

